controls.onPress:
{() => {
                            if (longPressedChoreRef.current === chore.id) {
                              longPressedChoreRef.current = null;
                              return;
                            }
                            handleChorePress(chore.id);
                          }}

{() => {
            if (calendarExpanded) {
              setSelectedDate((date) => new Date(date.getFullYear(), date.getMonth() - 1, 1, 12));
            } else {
              setWeekOffset((value) => value - 1);
            }
          }}

{() => {
            if (calendarExpanded) {
              setSelectedDate((date) => new Date(date.getFullYear(), date.getMonth() + 1, 1, 12));
            } else {
              setWeekOffset((value) => value + 1);
            }
          }}

{() => {
                        if (heldShoppingItem.current) return;
                        if (item.completed) {
                          shoppingFeedback.cancelCompletion(item.id);
                          tapLight();
                        } else {
                          shoppingFeedback.holdCompletion(item.id);
                          hapticSuccess();
                        }
                        toggleShoppingItem(item.id);
                      }}

{(event) => {
                                    event.stopPropagation();
                                    if (item.completed) {
                                      cancelCompletion(item.id);
                                    } else {
                                      completionOrderRef.current.set(list.id, items.map((entry) => entry.id));
                                      holdCompletion(item.id);
                                    }
                                    toggleShoppingItem(item.id);
                                    if (item.completed) tapLight();
                                    else hapticSuccess();
                                  }}

{() => {
                    assignShoppingList(
                      assignPickerListId!,
                      selected ? null : r.id
                    );
                    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                    setAssignPickerListId(null);
                  }}

{() => {
                    markAlertRead(feedItem.id);
                    if (feedItem.alert.type === "nudge") {
                      const nudgeId = feedItem.alert.id.replace(/^nudge:/, "");
                      void acknowledgeNudge(nudgeId).catch(() => {
                        hapticError();
                      });
                    } else if (feedItem.alert.relatedEntityType === "chore-chart") {
                      router.push("/planning?type=chore-chart" as never);
                    }
                  }}

controls.label:
{
              currentUserAssigned
                ? `Remove your assignment from ${item}`
                : `Assign yourself to ${item}`
            }

controls.onPress:
{() => {
              if (!customTaskTitle.trim()) return;
              addCustomTask({
                item: customTaskTitle.trim(),
                title: customTaskTitle.trim(),
                difficulty: customTaskDifficulty,
                frequency: customTaskFrequency,
                timeOfDay: customTaskTime,
              });
              setCustomTaskTitle("");
              setCustomTaskDifficulty(3);
            }}

controls.label:
{
                    setupMode
                      ? "Preview added essentials in Shopping"
                      : "View added essentials in Shopping"
                  }

controls.onPress:
{() => {
                    if (setupMode) {
                      setShoppingPreviewOpen(true);
                      return;
                    }
                    setShortlistOpen(false);
                    router.push("/(tabs)/shopping" as never);
                  }}

{(event) => {
                            event.stopPropagation();
                            confirm("leave_household", `Leave ${membership.name}?`, "You will lose access to this household’s shared data. Your other households are not affected.", () =>
                              leaveSweet(membership.sweetId), { confirmText: "Leave", destructive: true });
                          }}

{(value) =>
              void saveAnalyticsPreferences(userId, {
                [row.key]: value,
                noticeVersion: PRIVACY_NOTICE_VERSION,
                // Renew only the choice being explicitly changed, never revive
                // an older opt-in for the other category.
                ...(preferences.noticeVersion !== PRIVACY_NOTICE_VERSION
                  ? { [row.key === "productAnalyticsEnabled" ? "crashReportingEnabled" : "productAnalyticsEnabled"]: false }
                  : {}),
              }).catch(() => showPopup({ title: "Choice couldn't be saved", message: "Please try again.", actions: [{ label: "Got it", primary: true }] }))
            }

{() => {
        if (pressLocked.current) return;
        pressLocked.current = true;
        // Schedule unlocking before invoking consumer code: an exception must
        // not permanently turn every subsequent press into a no-op.
        setTimeout(() => {
          pressLocked.current = false;
        }, 450);
        onPress();
      }}

{() => {
            const targetHouseholdId = householdId;
            showPopup({
              title: "Edit household setup?",
              message: "Review and change your home type, shared items, and chore settings. Your current settings will be loaded for you to edit.",
              icon: "home",
              actions: [
                { label: "Cancel" },
                { label: "Edit setup", primary: true, onPress: () => {
                  if (activeHouseholdRef.current !== targetHouseholdId) return;
                  router.push(`/sweet-setup?resume=1&household=${targetHouseholdId}` as never);
                } },
              ],
            });
          }}

{() => {
                  if (navigationPendingRef.current) return;
                  navigationPendingRef.current = true;
                  router.push(`/planning?type=home-checklist&setup=household&housingType=${housingType}` as never);
                }}

{() => {
                          setFrequencyTarget({ sourceKey: chore.sourceKey, title: chore.title });
                          setFrequencyDraft(chore.persistedRecurrence);
                          setShowCustomFrequency(["everyOtherDay", "everyThreeDays"].includes(chore.persistedRecurrence));
                        }}

{() => {
              const previous = step === 2 ? "details" : step === 3 ? "home" : step === 4 ? (resumeExistingHousehold ? "home" : "essentials") : "items";
              void goToStep(previous);
              setError(null);
            }}

{async () => {
            try {
              const { error: signOutError } = await signOutWithPushCleanup();
              if (signOutError) {
                reportSupabaseError("sign out from household setup", signOutError);
                setError(signOutError.message);
              }
            } catch (signOutError) {
              reportRuntimeError("sign out from household setup", signOutError);
              setError("We couldn't sign you out. Please try again.");
            }
          }}

